source("pre.R")
set.seed(3); n <- 60
mk <- function() zutable(g = sample(c("a", "b", NA), n, TRUE), h = sample(c(1L, 2L, NA), n, TRUE), v = { v <- round(rnorm(n), 2); v[sample(n, 8)] <- NA; v[sample(n, 3)] <- NaN; v }, i = sample(c(-3:3, NA), n, TRUE), out = NA_real_, oi = NA_integer_, os = NA_character_)
df <- as.data.frame(mk())
cat("--- := by vs over vs grouped join\n")
a <- mk(); a[, out := sum(v), by = .(g, h)]
b <- mk()[select = .(g, h, v, i, out = over(sum(v), by = .(g, h)), oi, os)]
print(identical(as.data.frame(a)$out, as.data.frame(b)$out))
ar <- mk(); ref(ar[, out := sum(v), by = .(g, h)]); print(identical(a$out, ar$out))
gr <- mk()[by = .(g, h), select = .(s = sum(v))]; j <- join(mk(), gr, on = .(g, h), how = "left"); print(identical(j$s, a$out))
upd <- function(expr) { e <- substitute(expr); x <- mk(); r1 <- tryCatch({ eval(e); as.data.frame(x) }, error = function(err) conditionMessage(err)); x <- mk(); r2 <- ref(tryCatch({ eval(e); as.data.frame(x) }, error = function(err) conditionMessage(err))); cat(if (identical(r1, r2)) "same" else "DIFF", "|", substr(paste(deparse(e), collapse = " "), 1, 90), if (is.character(r1)) paste("\n    ->", r1), "\n"); invisible(r1) }
upd(x[, out := v * 2]); upd(x[i > 0, out := mean(v)]); upd(x[i > 0, out := v - mean(v), by = g]); upd(x[, { w <- v * i; out := w; oi := count(w) }, by = h]); upd(x[, { out := max(v); oi := i %/% 2L; os := first(g) }, by = .(g, h)])
upd(x[, oi := .N, by = g]); upd(x[, oi := count_distinct(i), by = g]); upd(x[, os := max(g)]); upd(x[, os := concat(g, "-", cast(h, string))]); upd(x[is.na(g), os := "none"]); upd(x[, { out := 1; out := out + 1; v := out }]); upd(x[, { v := 0; out := sum(v) }, by = g])
upd(x[g == "a", { v := 0; out := sum(v) }, by = h]); upd(x[, g := NA]); upd(x[, v := NaN]); upd(x[, i := 2^31]); upd(x[, i := i * 1000000000L]); upd(x[, i := 1.0]); upd(x[, oi := v]); upd(x[, out := i]); upd(x[, out := i, by = g]); upd(x[, out := sum(i) / .N, by = g]); upd(x[, os := r(paste0(g, h), string)]); upd(x[, out := r(mean(v, na.rm = TRUE), float64), by = g]); upd(x[, out := c(1, 2)]); upd(x[, zz := 1]); upd(x[, c("out", "v") := 1]); upd(x[, out := NULL]); upd(x[, `:=`(out, 1)]); upd(x[, out := (w <- 1)]); upd(x[v > 0 & i > 0, out := first(v), by = g]); upd(x[v > 100, out := first(v), by = g]); upd(x[, out := last(v) - first(v), by = .(k = i %% 2L)]); upd(x[, out := mean(v), by = "g"]); upd(x[, out := ifelse(v > mean(v), 1, 0), by = g]); upd(x[, out := case(v > 0 ~ sum(v), .default = min(v)), by = g]); upd(x[, oi := cast(sum(i), int32), by = g]); upd(x[, out := sum(v), by = v]); upd(x[update = out := 1, where = i > 0]); upd(x[i > 0, update = { out := 2 }])
x <- mk(); r <- x[, out := 1]; print(identical(r, x)); y <- x[i > 0, out := 5][, .(out)]; print(table(y$out, useNA = "a"))
cat("--- failure atomicity\n")
x <- mk(); before <- as.data.frame(x); try_(x[, { out := 1; i := i * 1000000000L }]); print(identical(before, as.data.frame(x))); try_(x[, { out := 1; oi := r(v, int32) }]); print(identical(before, as.data.frame(x)))
nn <- as_zutable(data.frame(a = 1:3, b = c(1, NA, 3)), schema(a = not_null(int32), b = float64)); try_(nn[, { b := 0; a := cast(b / 0, int32) }]); print(as.data.frame(nn)); try_(nn[b > 1, a := NA]); print(nn$a)
cat("--- select/having/order details\n")
x <- mk()
both(x[by = g, select = .(n = .N, s = sum(v)), having = n > 15 & s > -100, order = desc(n)]); both(x[select = .(g, w = v * 2), order = .(desc(w), g), limit = 7]); both(x[select = .(g, w = v * 2), order = i, limit = 7]); both(x[by = .(k = i %% 2L), select = .(k2 = k + 1L, n = .N), order = k]); both(x[by = g, select = .(g, n = .N)]); both(x[by = .(g, h), select = .(r = sum(v) / count(v), mx = max(i) - min(i), gg = concat(g, "!"))]); both(x[select = .(d = max(v) - min(v), n = count(v), m = mean(i))]); both(x[having = count() > 1, select = .(n = .N)]); both(x[by = g, having = max(v) > 1]); both(x[distinct = TRUE, select = .(g, h), order = .(g, desc(h))]); both(x[order = .(g, h, desc(v)), limit = 10]); both(x[i %in% c(1, 2) & !is.na(v), .(g, i)][order = g]); both(x[by = h, select = .(a = any(v > 1), b = all(i > -2), f = first(g), l = last(g))])
print(try_(x[select = .(g), order = desc(g, h)])); print(try_(x[select = .(g), order = desc(desc(g))]$g[1:3])); print(try_(x[order = "g"])); print(try_(x[order = 1])); print(try_(x[select = .(n = .N), order = g])); print(try_(x[by = g, select = .(n = .N), order = v])); print(try_(x[distinct = TRUE, select = .(g), order = h]))
cn <- "v"; print(try_(nrow(x[.col(cn) > 0]))); print(try_(nrow(x[.col("nope") > 0]))); g <- "a"; print(try_(nrow(x[g == ..g]))); print(try_(nrow(x[g == g]))); v <- 0; print(nrow(x[v > ..v])); print(try_(nrow(x[v > ..nope])))
print(try_(x[select = .(.all, -g, -h)][1, ])); print(try_(x[select = .(-g, .all)])); print(try_(x[select = .(.all, g2 = g, -g)][1, ])); print(try_(x[select = .(.all, g = h)])); print(try_(x[select = .(.all, .all)])); print(try_(x[select = .()])); print(try_(x[select = g])); print(try_(x[select = "g"])); print(try_(x[select = v + 1])); print(try_(x[select = .(v + 1)])); print(try_(x[select = .(a = NA)])); print(try_(x[, .(a = na(int32))][1, ])); print(try_(x[where = v])); print(try_(x[where = sum(v) > 1])); print(try_(x[foo = 1])); print(try_(x[i > 0, where = v > 0])); print(try_(x[, .(g), select = .(h)])); print(try_(x[1:3, .(g)])); print(try_(x[, .(g)][1:2])); print(try_(x[, 1:2][1, ]))
cat("--- explain\n"); explain(x[i > 0 & v < 0.30000000000000004, .(g, w = v * 2)][order = desc(w), limit = 3]); y <- mk(); y[i > 0, out := sum(v), by = g]; explain(y); y$v <- 0; explain(y); explain(copy(y)); explain(y[1:2]); explain(rbind(y, y)); print(try_(explain(1)))
cat("--- print n\n"); print(x, n = 2); print(x[0]); try_(print(x, n = 0)); try_(print(x, n = -1)); try_(print(x, n = NA)); try_(print(x[1:3], n = Inf)); try_(print(x[1:3], n = 2.5))
